-- Review-local identifiers and source status are not production EMMA identifiers.
CREATE SCHEMA research_register;
CREATE TABLE research_register.migration_source (source_name VARCHAR PRIMARY KEY, sha256 VARCHAR NOT NULL, purpose VARCHAR NOT NULL);
CREATE TABLE research_register.workshop (workshop_id VARCHAR PRIMARY KEY, workbook_path VARCHAR NOT NULL, workbook_md5 VARCHAR NOT NULL, rank_definition VARCHAR NOT NULL, identifier_note VARCHAR NOT NULL, method VARCHAR NOT NULL);
CREATE TABLE research_register.workshop_limitation (workshop_id VARCHAR NOT NULL REFERENCES research_register.workshop(workshop_id), position INTEGER NOT NULL, limitation VARCHAR NOT NULL, PRIMARY KEY(workshop_id, position));
CREATE TABLE research_register.workshop_reach (reach_id VARCHAR PRIMARY KEY, workshop_id VARCHAR NOT NULL REFERENCES research_register.workshop(workshop_id), label VARCHAR NOT NULL, position INTEGER NOT NULL);
CREATE TABLE research_register.workshop_goal (goal_id INTEGER PRIMARY KEY, goal_text VARCHAR NOT NULL UNIQUE);
CREATE TABLE research_register.workshop_objective (objective_id INTEGER PRIMARY KEY, goal_id INTEGER NOT NULL REFERENCES research_register.workshop_goal(goal_id), objective_text VARCHAR NOT NULL, UNIQUE(goal_id, objective_text));
CREATE TABLE research_register.workshop_question (question_id VARCHAR PRIMARY KEY, workshop_id VARCHAR NOT NULL REFERENCES research_register.workshop(workshop_id), objective_id INTEGER NOT NULL REFERENCES research_register.workshop_objective(objective_id), source_cell VARCHAR NOT NULL, question_text VARCHAR NOT NULL);
CREATE TABLE research_register.workshop_rank (question_id VARCHAR NOT NULL REFERENCES research_register.workshop_question(question_id), reach_id VARCHAR NOT NULL REFERENCES research_register.workshop_reach(reach_id), rank_value DOUBLE NOT NULL CHECK(rank_value >= 1 AND rank_value <= 49), PRIMARY KEY(question_id, reach_id));
CREATE TABLE research_register.workshop_project_mark (mark_id INTEGER PRIMARY KEY, question_id VARCHAR NOT NULL REFERENCES research_register.workshop_question(question_id), reach VARCHAR NOT NULL, source_cell VARCHAR NOT NULL, project_label VARCHAR NOT NULL, mark VARCHAR NOT NULL);
CREATE TABLE research_register.pilot_question_link (question_id VARCHAR PRIMARY KEY REFERENCES research_register.workshop_question(question_id), role VARCHAR NOT NULL, rationale VARCHAR NOT NULL, record_status VARCHAR NOT NULL, scope_note VARCHAR NOT NULL);
CREATE TABLE research_register.science_source (source_id VARCHAR PRIMARY KEY, zotero_item_key VARCHAR, doi VARCHAR, source_url VARCHAR, reading_depth VARCHAR NOT NULL);
CREATE TABLE research_register.science_assertion (assertion_id VARCHAR PRIMARY KEY, source_id VARCHAR REFERENCES research_register.science_source(source_id), assertion_kind VARCHAR NOT NULL, paraphrase VARCHAR NOT NULL, source_locator VARCHAR, limitation VARCHAR, extraction_status VARCHAR NOT NULL, full_text_scope VARCHAR);
CREATE TABLE research_register.assertion_derivation (assertion_id VARCHAR NOT NULL REFERENCES research_register.science_assertion(assertion_id), informed_by_id VARCHAR NOT NULL REFERENCES research_register.science_assertion(assertion_id), PRIMARY KEY(assertion_id, informed_by_id));
